<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN']);$db=Database::connection();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=mb_strtolower(trim($_POST['email']));$password=(string)$_POST['password'];if(filter_var($email,FILTER_VALIDATE_EMAIL)&&strlen($password)>=8){$db->prepare("INSERT INTO utilisateurs(role_id,nom,prenom,email,mot_de_passe,statut) VALUES(?,?,?,?,?,'actif')")->execute([(int)$_POST['role_id'],trim($_POST['nom']),trim($_POST['prenom']),$email,password_hash($password,PASSWORD_DEFAULT)]);audit('CREATION','utilisateur',(int)$db->lastInsertId());flash('success','Utilisateur créé.');}else flash('danger','Données invalides.');redirect('utilisateurs/index.php');}$roles=$db->query('SELECT id,nom FROM roles')->fetchAll();$rows=$db->query('SELECT u.*,r.nom role FROM utilisateurs u JOIN roles r ON r.id=u.role_id ORDER BY u.created_at DESC')->fetchAll();$title='Utilisateurs';require __DIR__.'/../../includes/header.php';?>
<div class="page-heading"><h1 class="h3">Utilisateurs et rôles</h1></div><form method="post" class="card card-body mb-3"><?= csrf_field() ?><div class="row g-2"><div class="col"><input class="form-control" name="prenom" placeholder="Prénom" required></div><div class="col"><input class="form-control" name="nom" placeholder="Nom" required></div><div class="col"><input type="email" class="form-control" name="email" placeholder="E-mail" required></div><div class="col"><select class="form-select" name="role_id"><?php foreach($roles as $r): ?><option value="<?= $r['id'] ?>"><?= e($r['nom']) ?></option><?php endforeach ?></select></div><div class="col"><input type="password" class="form-control" name="password" minlength="8" required placeholder="Mot de passe"></div><div class="col-auto"><button class="btn btn-primary">Créer</button></div></div></form><div class="card"><table class="table mb-0"><thead><tr><th>Utilisateur</th><th>E-mail</th><th>Rôle</th><th>Statut</th><th>Connexion</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['prenom'].' '.$r['nom']) ?></td><td><?= e($r['email']) ?></td><td><?= e($r['role']) ?></td><td><?= e($r['statut']) ?></td><td><?= e($r['derniere_connexion']) ?></td></tr><?php endforeach ?></tbody></table></div><?php require __DIR__.'/../../includes/footer.php'; ?>
